/* Original DOS/Windows observations are generated by the Unicorn verifier.
 * Include ai.c to exercise the real attack_manoeuvre reaction, including its
 * RNG consumption and queued-manoeuvre handling, without unrelated AIT rules. */
#include <stdio.h>
#include <string.h>
#include "../src/ai.c"
#include "../tests/fixtures/ai-validation/mercs_ai_cases.h"

static int failures;

static void check_reaction(const mercs_ai_reaction_case *c)
{
    ai_mind m;
    ai_view v;
    float radius=0, distance=0;
    int threshold=ai_mercs_gps5_threshold((uint16_t)c->raw,c->previous);
    ai_init(&m,AIP_DEFLT);
    memset(&v,0,sizeof v);
    m.state=c->ai_state;
    m.man=c->man;
    m.prev_man=c->prev;
    m.forced_man=c->forced;
    m.man_limit=1000000;
    m.rng=c->seed;
    v.has_enemy=1;
    v.enemy_dist=100000;
    v.moving=c->moving;
    v.out_of_weapons=c->empty;
    v.can_jump=c->can_jump;
    v.heat=(float)c->heat;
    v.jet_fuel=10;
    v.pilot_level=c->normalized_level;
    v.unit_class=c->unit_class;
    v.charge_flee_threshold=threshold;
    attack_manoeuvre(&m,&v,1,&radius,&distance);
    if (threshold!=c->threshold || m.forced_man!=c->want_forced ||
        m.queue5!=c->want_queue || m.rng!=c->want_rng) {
        fprintf(stderr,"%s: threshold %d/%d, manoeuvre %d/%d, queue %d/%d, rng %u/%u\n",
                c->name,threshold,c->threshold,m.forced_man,c->want_forced,
                m.queue5,c->want_queue,m.rng,c->want_rng);
        failures++;
    }
}

int main(void)
{
    size_t i;
    for(i=0;i<sizeof mercs_ai_setup_cases/sizeof mercs_ai_setup_cases[0];i++) {
        const mercs_ai_setup_case *c=&mercs_ai_setup_cases[i];
        int result=ai_mercs_gps5_threshold((uint16_t)c->raw,c->previous);
        if(result!=c->threshold) {
            fprintf(stderr,"GPS5 raw %d previous %d: expected %d got %d\n",
                    c->raw,c->previous,c->threshold,result);
            failures++;
        }
    }
    for(i=0;i<sizeof mercs_ai_reaction_cases/sizeof mercs_ai_reaction_cases[0];i++)
        check_reaction(&mercs_ai_reaction_cases[i]);
    if(failures) return 1;
    printf("PASS: %zu original GPS5 setup cases and %zu original DOS/Windows attack-reaction cases\n",
           sizeof mercs_ai_setup_cases/sizeof mercs_ai_setup_cases[0],i);
    return 0;
}
